"""Synthetic only; no real source approvals are generated by these tests."""
import copy, unittest
from pathlib import Path
import evidence as e
import customer_observations as co
import test_release as rel
import test_source_verifier as sv
ROOT=Path(__file__).resolve().parents[1]
REG={'synthetic-claim-reviewer':['claim_verifier'],'synthetic-reviewer':['source_verifier']}

class CustomerTests(unittest.TestCase):
 def fixture(self,kind='customer_project_observation',source='customer_project_report'):
  d=rel.ReleaseTests().fixture();c=d['claims'][0];s=d['sources'][0]
  c.update(claim_type=kind,customer_scope=co.EXTENSION,customer_subject={'customer_id':'synthetic-customer','customer_name':'Synthetic Customer','company_id':c['company_id'],'project_or_product':'Synthetic Product','site':'Synthetic Campus','relationship_basis':'Synthetic customer project report'},time={'kind':'unknown','basis':'Precise event time is not reported.','event_time':None})
  s.update(source_type=source,relationship='customer_project_party',publication_date='2026-09-01',editorial_authority_rationale='Synthetic original customer interview, not copied issuer PR')
  c['evidence'][0]['customer_attribution']={k:c['customer_subject'][k] for k in ('customer_id','company_id','project_or_product','site')}
  c['evidence'][0]['customer_attribution'].update(original_witness='Synthetic named customer',factual_origin_id='synthetic-customer-project',origin_role='customer_or_project_party',competence_rationale='Synthetic customer directly describes own project.',relationship_disclosures='Synthetic customer is interested party.',correction_disposition='Synthetic fixture has no corrections.',report_date=s['publication_date'],report_date_basis='source_publication_only',event_time=None)
  c['predicate_review']={'supported_claim_type':kind,'rationale':'Synthetic customer semantic review only','customer_scope_checked':True,'unknown_event_time_checked':True,'corrections_conflicts_checked':True,'extension_policy_sha256':co.policy_hash()}
  for r in d['research_plan']['routes']:r['claim_types']=[kind]
  self.sign(d);return d
 def sign(self,d):
  c=d['claims'][0]
  c['reviews'][0].update(claim_sha256=e.digest_claim(c),source_snapshot_sha256=e.source_snapshot(d))
  sv.SourceVerifierTests().sign(d)
  d['source_review'].update(customer_extension_sha256=co.policy_hash(),customer_claim_ids=[c['id']],customer_authority_and_temporal_scope_checked=True)
  d['rollout']['acknowledgements'].append({'actor':'synthetic-claim-reviewer','policy':e.POLICY,'policy_sha256':e.sha((ROOT/'POLICY.md').read_bytes()),'acknowledged_at':'2026-10-03T00:00:00Z'})
  for a in d['rollout']['acknowledgements']:a.update(customer_extension=co.EXTENSION,customer_extension_sha256=co.policy_hash())
 def runreport(self,d,registry=REG):return e.report(d,ROOT,e.date('2026-10-10'),registry)
 def row(self,d,registry=REG):return self.runreport(d,registry)['augmented_observations'][0]
 def test_primary_and_secondary_both_types(self):
  for kind in co.CUSTOMER_TYPES:
   for source in ('customer_project_report','independent_reporting'):
    d=self.fixture(kind,source);r=self.row(d)
    self.assertEqual(r['release_status'],'RELEASED_RESEARCH_FINDING',r)
    self.assertEqual(r['evidence_tier'],'PRIMARY_ATTRIBUTED' if source=='customer_project_report' else 'SECONDARY_ATTRIBUTED')
 def test_known_report_unknown_event_separate(self):
  r=self.row(self.fixture());self.assertEqual(r['time']['kind'],'unknown');self.assertEqual(r['report_dates'][0]['report_date'],'2026-09-01');self.assertIsNone(r['report_dates'][0]['event_time'])
 def test_no_survival_finance_censor_promotion(self):
  r=self.row(self.fixture())
  for key in co.EXCLUDED:self.assertIn(r[key],(None,False))
 def test_dates_cannot_be_substituted(self):
  for key in ('on','start','end','event_time','event_timezone','censor_date'):
   d=self.fixture();d['claims'][0]['time'][key]='2026-09-01';self.sign(d)
   with self.subTest(key=key),self.assertRaises(ValueError):self.runreport(d)
 def test_point_or_period_not_accepted(self):
  for kind in ('point','activity_period','upper_bound','event_interval'):
   d=self.fixture();d['claims'][0]['time'].update(kind=kind,on='2026-09-01',start='2026-09-01',end='2026-09-01');self.sign(d)
   with self.subTest(kind=kind),self.assertRaises(ValueError):self.runreport(d)
 def test_report_date_must_match_source(self):
  d=self.fixture();d['claims'][0]['evidence'][0]['customer_attribution']['report_date']='2026-09-02';self.sign(d)
  with self.assertRaises(ValueError):self.runreport(d)
 def test_report_date_must_be_known(self):
  d=self.fixture();d['sources'][0]['publication_date']=None;d['claims'][0]['evidence'][0]['customer_attribution']['report_date']=None;self.sign(d)
  with self.assertRaises(ValueError):self.runreport(d)
 def test_wrong_customer_company_product_or_site(self):
  for key in ('customer_id','company_id','project_or_product','site'):
   d=self.fixture();d['claims'][0]['evidence'][0]['customer_attribution'][key]='unrelated';self.sign(d)
   with self.subTest(key=key),self.assertRaises(ValueError):self.runreport(d)
 def test_issuer_quote_cannot_be_customer_testimony(self):
  d=self.fixture(source='independent_reporting');d['claims'][0]['evidence'][0]['customer_attribution']['origin_role']='issuer';self.sign(d)
  with self.assertRaises(ValueError):self.runreport(d)
 def test_competence_and_qualifications_required(self):
  for key in ('original_witness','factual_origin_id','competence_rationale','relationship_disclosures','correction_disposition'):
   d=self.fixture();d['claims'][0]['evidence'][0]['customer_attribution'][key]='';self.sign(d)
   with self.subTest(key=key),self.assertRaises(ValueError):self.runreport(d)
 def test_unqualified_primary_authority_held(self):
  d=self.fixture();d['sources'][0]['relationship']='unrelated';self.sign(d);self.assertIn('PRIMARY_CUSTOMER_RELATIONSHIP_UNQUALIFIED',self.row(d)['reasons'])
 def test_issuer_and_registry_not_customer_authorities(self):
  for source in ('issuer_announcement','official_registry','platform_issuer_report','specialist_database'):
   d=self.fixture(source=source);self.assertIn('NO_CLAIM_APPROPRIATE_AUTHORITY',self.row(d)['reasons'])
 def test_customer_not_issuer_authority(self):
  self.assertNotIn('customer_project_report',e.ALLOW['operating_activity'])
  for kind in ('operating_activity','priced_equity','realized_investor_return'):
   d=self.fixture();d['claims'][0]['claim_type']=kind;self.sign(d)
   with self.subTest(kind=kind),self.assertRaises(ValueError):self.runreport(d)
 def test_pending_null_review_held(self):
  d=self.fixture();d['claims'][0]['predicate_review']=None;d['claims'][0]['reviews']=[];self.assertEqual(self.row(d)['status'],'HELD')
 def test_origin_or_correction_edit_invalidates_hash_review(self):
  for field in ('origin_family','correction'):
   d=self.fixture();d['sources'][0][field]='changed'
   with self.subTest(field=field),self.assertRaises(ValueError):self.runreport(d)
 def test_customer_edit_invalidates_claim_review(self):
  d=self.fixture();d['claims'][0]['customer_subject']['customer_name']='New name'
  with self.assertRaises(ValueError):self.runreport(d)
 def test_capture_tamper_rejected(self):
  d=self.fixture();d['sources'][0]['capture_sha256']='0'*64
  with self.assertRaises(ValueError):self.runreport(d)
 def test_old_source_review_cannot_reuse(self):
  d=self.fixture();d['source_review'].pop('customer_extension_sha256');self.assertEqual(self.row(d)['release_status'],'UNRELEASED_RESEARCH_OBSERVATION')
 def test_old_semantic_review_cannot_reuse(self):
  d=self.fixture();d['claims'][0]['predicate_review']['extension_policy_sha256']='0'*64;self.sign(d);self.assertEqual(self.row(d)['status'],'HELD')
 def test_acknowledgement_required(self):
  d=self.fixture();d['rollout']['acknowledgements'][0].pop('customer_extension');self.assertEqual(self.row(d)['release_status'],'UNRELEASED_RESEARCH_OBSERVATION')
 def test_registry_required(self):self.assertEqual(self.row(self.fixture(),{})['release_status'],'UNRELEASED_RESEARCH_OBSERVATION')
 def test_reviewer_cannot_fill_both_roles(self):
  d=self.fixture();d['source_review']['reviewer']='synthetic-claim-reviewer';self.assertIn('CUSTOMER_REVIEWERS_NOT_DISTINCT',self.runreport(d)['source_coverage_audit']['blockers'])
 def test_contradictory_testimony_holds(self):
  d=self.fixture();d['claims'][0]['evidence'].append({**copy.deepcopy(d['claims'][0]['evidence'][0]),'stance':'contradicts'});self.sign(d);self.assertIn('OPEN_CONTRADICTION',self.row(d)['reasons'])
 def test_outcome_fields_forbidden(self):
  for key in co.EXCLUDED:
   d=self.fixture();d['claims'][0][key]='promoted';self.sign(d)
   with self.subTest(key=key),self.assertRaises(ValueError):self.runreport(d)
 def test_stale_observation_never_extended(self):
  d=self.fixture();r=e.report(d,ROOT,e.date('2030-01-01'),REG)['augmented_observations'][0];self.assertIsNone(r['point_censor_date']);self.assertEqual(r['time']['kind'],'unknown')
 def test_future_report_holds(self):
  d=self.fixture();d['sources'][0]['publication_date']='2027-01-01';d['claims'][0]['evidence'][0]['customer_attribution']['report_date']='2027-01-01';self.sign(d);self.assertIn('SOURCE_POSTDATES_AS_OF',self.row(d)['reasons'])

 def test_future_correction_holds(self):
  d=self.fixture();d['sources'][0]['correction']={'date':'2027-01-01','scope':'Changed context'};self.sign(d);self.assertIn('CUSTOMER_CORRECTION_POSTDATES_AS_OF',self.row(d)['reasons'])
 def test_mixed_incompetent_support_holds(self):
  d=self.fixture();s=copy.deepcopy(d['sources'][0]);s.update(id='issuer',source_type='issuer_announcement');d['sources'].append(s);ev=copy.deepcopy(d['claims'][0]['evidence'][0]);ev['source_id']='issuer';d['claims'][0]['evidence'].append(ev);self.sign(d);self.assertIn('UNQUALIFIED_CUSTOMER_SUPPORT_SOURCE',self.row(d)['reasons'])

 def test_strict_calendar_date(self):
  for bad in ('20260901','2026-W36-2','2026-9-01','2026-02-30'):
   d=self.fixture();d['sources'][0]['publication_date']=bad;d['claims'][0]['evidence'][0]['customer_attribution']['report_date']=bad;self.sign(d)
   with self.subTest(date=bad),self.assertRaises(ValueError):self.runreport(d)
 def test_primary_customer_identity_only_does_not_release_old_claim(self):
  import test_scoped_review as f
  h=f.ScopedTests();d=h.fixture();s=copy.deepcopy(d['sources'][0]);s['id']='identity-only-source';d['sources'].append(s);d['claims'][0]['identity']['evidence_source_ids']=[s['id']];h.sign(d);d['source_review']['origin_assessments'][s['id']]['kind']='primary_customer';r=h.runreport(d)
  self.assertEqual(r['released_selected_claims'],0)
  self.assertIn('FACTUAL_ORIGIN_UNREVIEWED:identity-only-source',r['scope']['blockers'])
